package android.os; import java.util.ArrayDeque;public class Handler {public static boolean accepted=true;public static final ArrayDeque<Runnable> tasks=new ArrayDeque<Runnable>();public Handler(Looper l){}public boolean post(Runnable r){if(accepted)tasks.add(r);return accepted;}public static void drain(){Looper.ui=true;while(!tasks.isEmpty())tasks.remove().run();Looper.ui=false;}}
